files.docs/spec/sigil-glossary.sigil:
@docs/spec/sigil-config.sigil from SpecWorkspaceConfig import {
  workspace root,
}
@docs/spec/sigil-reference.sigil from SpecLanguageReference import {
  facet,
  name matching,
  source range,
  tag identity,
}

component SpecWorkspaceGlossary {
  goal {
    Give a workspace one reviewed vocabulary so that tools and editors
    recognize the same terms in design prose.
  }

  constraints {
    A workspace glossary must not change Sigil syntax, create a tag identity,
    or rename a tag identity to match a glossary term.

    A glossary term must not override a facet, and the facet stays normative
    when the two conflict.

    Two glossary context entries must not claim the same source.

    Reporting a workspace glossary must be read-only and must not extract,
    propose, or change a glossary term.

    A glossary occurrence must follow name matching, except that it ignores
    case.
  }

  interface {
    SpecWorkspaceGlossary provides the *workspace glossary*, an optional,
    strict JSON file under the workspace root that people review and commit.
    Its absence is valid.

    SpecWorkspaceGlossary provides the *glossary term*, a canonical spelling
    with a definition and aliases, which an agent-context flag can hide from
    agent-facing context without affecting validation or editor features.

    SpecWorkspaceGlossary provides the *glossary context*, a bounded set of
    sources chosen by globs, inside which its glossary term entries replace
    the workspace spelling.

    SpecWorkspaceGlossary provides the *glossary occurrence*, a glossary term
    found in facet prose by name matching, with its canonical term, matched
    spelling, owner, and source range.
  }

  decisions {
    The workspace glossary stays apart from Sigil syntax, so that accepted
    Sigil remains the normative design while people review the vocabulary.
  }
}

files.integrations/editor/vscode/extension.sig:
@docs/spec/sigil-config.sigil from SpecWorkspaceConfig import {
  tool settings,
  workspace root,
}
@docs/spec/sigil-reference.sigil from SpecLanguageReference import { source document }
@packages/cli/cli.sigil from SigilCli import { lsp command }
@packages/lsp/lsp.sigil from SigilLsp import {
  language server,
  render command,
}
@packages/sigilc/claims.sigil from SigilComputedClaims import { ComputedFindings }
@packages/sigilc/compiler.sigil from SigilSemanticCompiler import { CompilerCommands }

component SigilVsCodeExtension {
  goal {
    Give VS Code users Sigil editing support and a one-step compile, using the
    sigil language server and the sigilc compiler.
  }

  constraints {
    SigilVsCodeExtension depends on SigilLsp for the language server and on
    SigilSemanticCompiler for the CompilerCommands, and must not parse or
    resolve a source document itself.

    The extension must start the language server by running the lsp command,
    and must not bundle a language server of its own.

    The extension must support only a trusted workspace whose workspace root is
    a folder on disk.

    The extension must show each of the ComputedFindings as an editor
    diagnostic, with the law that produced it as its code, and as a status
    entry, and must mark the result stale when a workspace input or a compile
    setting changes after the compile began.

    The extension must run a compile through the CompilerCommands and must not
    change any source document.
  }

  interface {
    SigilVsCodeExtension provides the *Sigil grammar*, the syntax highlighting
    and bracket rules for .sigil files.

    SigilVsCodeExtension provides the *component preview*, a read-only Markdown
    view of the active source document, which comes from the render command.

    SigilVsCodeExtension provides *compile file* and *compile workspace*,
    which run a compile for the active file or for the whole workspace root and
    show its result.

    SigilVsCodeExtension provides the *compile focus*, design or
    implementation. Design judges design readiness. Implementation compares the
    code that the tool settings select with the design. The compile focus
    setting chooses one, or asks each time, except that compile file on a
    source document is always design.

    SigilVsCodeExtension provides the *compile executable setting*,
    sigil.compile.executable, the path of the sigilc compiler, which defaults
    to sigilc.

    SigilVsCodeExtension provides the *compile focus setting*,
    sigil.compile.focus, with the values ask, design or implementation, which
    defaults to ask.
  }

  decisions {
    SigilVsCodeExtension stays a thin client, so that VS Code shows the same
    Sigil results as the command line.
  }
}

files.packages/cli/cli.sigil:
@docs/spec/sigil-config.sigil from SpecWorkspaceConfig import {
  language version,
  workspace config,
  workspace discovery,
  workspace root,
}
@docs/spec/sigil-glossary.sigil from SpecWorkspaceGlossary import {
  glossary occurrence,
  workspace glossary,
}
@docs/spec/sigil-reference.sigil from SpecLanguageReference import {
  diagnostic code,
  source document,
  source range,
}
@packages/core/core.sigil from SigilCore import {
  formatted source,
  workspace snapshot,
}

component SigilCli {
  goal {
    Give people and skills one command line, sigil, to check, format and
    inspect a Sigil workspace, and to start the language server.
  }

  constraints {
    SigilCli depends on SigilCore for the workspace snapshot and the formatted
    source, and must not read a source document by any other path.

    Except for the init command, SigilCli must find the workspace config by
    workspace discovery from the target path, or the current directory when
    there is none, or from an explicit workspace root.

    SigilCli must report every diagnostic with its diagnostic code and exit
    with exit status 1 when any diagnostic is an error.

    The fmt command must write nothing when any selected source document has an
    error that SigilCore refuses to format, and with its check option must
    change no file and must exit with exit status 1 when any file is
    noncanonical.

    The check command must report only the diagnostics of the workspace
    snapshot, and none about implementation sources.

    SigilCli must treat a removed command, graph, context, retrieve or render,
    as invalid usage and must not read the workspace for it.
  }

  interface {
    SigilCli provides the *init command*, which writes a new workspace config,
    keeps an existing workspace glossary, and refuses to overwrite a workspace
    config.

    SigilCli provides the *version command*, which reports the CLI version, the
    core version and the language version of the workspace.

    SigilCli provides the *parse command*, which reports one source document
    with a source range for each of its parts.

    SigilCli provides the *check command*, which reports the diagnostics of the
    workspace and their count for each severity.

    SigilCli provides the *fmt command*, which writes the formatted source of
    each selected source document that changed, validates every selected
    source document before it writes, and reports each file as formatted,
    unchanged, noncanonical or failed.

    SigilCli provides the *glossary command*, which reports the workspace
    glossary with each glossary occurrence it finds in the workspace.

    SigilCli provides the *lsp command*, which starts the language server on
    standard input and output for an editor. sigilc stays a separate
    executable and is not a sigil command.

    SigilCli provides each command's *output format*, json, text, or markdown,
    except that the fmt command offers only json and text.

    SigilCli provides *exit status* 0 for success, 1 for an error diagnostic, 2
    for invalid usage and 3 for a runtime failure.

    SigilCli provides *invalid usage* as the refusal of an unknown command or
    option, with exit status 2 and nothing on standard output.
  }

  decisions {
    SigilCli keeps no language logic, so that every command and the language
    server read a Sigil workspace the way sigilc does.
  }
}

files.packages/lsp/lsp.sigil:
@docs/spec/sigil-config.sigil from SpecWorkspaceConfig import { workspace config }
@docs/spec/sigil-glossary.sigil from SpecWorkspaceGlossary import {
  glossary context,
  glossary occurrence,
  glossary term,
  workspace glossary,
}
@docs/spec/sigil-reference.sigil from SpecLanguageReference import {
  diagnostic code,
  facet,
  source document,
  tag identity,
}
@packages/cli/cli.sigil from SigilCli import { lsp command }
@packages/core/core.sigil from SigilCore import {
  caller-supplied text,
  editor position,
  workspace snapshot,
}

component SigilLsp {
  goal {
    Give editors the language features of a Sigil workspace over the Language
    Server Protocol, from the same reading that the sigil command uses.
  }

  constraints {
    SigilLsp depends on SigilCore for the workspace snapshot and each editor
    position, and must not read a source document or a tag identity a second
    way.

    SigilLsp must report every position as an editor position in UTF-16 units.

    SigilLsp must give SigilCore each open unsaved buffer as caller-supplied text,
    so that a published diagnostic describes the buffer, and describes the disk
    file again once the buffer closes.

    SigilLsp must answer each request from one workspace snapshot, so that
    definition links, tag hover and semantic tokens agree on each tag identity.

    A late reload must not overwrite a newer unsaved buffer, and a request that
    outlives its workspace snapshot must be answered as content modified.

    SigilLsp must reload the workspace snapshot when a watched source document,
    the workspace config or the workspace glossary changes.

    Tag hover must show the provider contract with the facet of each consumer
    that uses the tag identity, and must not show implementation ownership.

    The language server must not add completion, references, rename,
    formatting or code actions.
  }

  interface {
    SigilLsp provides the *language server*, which the lsp command starts. It
    speaks the Language Server Protocol on standard input and output with
    initialize, initialized, shutdown and exit, and synchronizes whole open
    source documents.

    SigilLsp provides each *published diagnostic* with its diagnostic code and
    related locations, for every diagnostic of the workspace snapshot.

    SigilLsp provides a *definition link* from a tag identity use to the inline
    definition that owns it, or else to the earliest valid grouping heading,
    and from a glossary occurrence to its entry in the workspace glossary.

    SigilLsp provides *document symbols* for components, sections, local tag
    groups and inline definitions.

    SigilLsp provides *tag hover*, and shows a glossary occurrence with its
    glossary context and the canonical spelling and definition of its glossary
    term.

    SigilLsp provides *semantic tokens* of type for a component name, tag for a
    tag identity and term for a glossary occurrence.

    SigilLsp provides the *render command*, sigil.renderDocument, which returns
    the Markdown of every component declared in one source document.
  }

  decisions {
    SigilLsp stays a thin bridge over SigilCore, so that an editor never shows
    a Tag, a diagnostic or a glossary term that the sigil command would not.
  }
}

files.packages/sigilc/compiler.sigil:
component SigilSemanticCompiler {
  goal {
    Turn authored Sigil sources into resolved SourceTrees, compute design
    results from caller supplied language interpretation, and compare design
    commitments with supplied implementation readings.
  }

  interface {
    *language interpretation* Caller supplied semantic readings consumed by
    computed design claims; the compiler does not invoke a model.

    *CompilerCommands* Provide one native executable for tree inspection,
    computed design claims, implementation alignment, and disposable cache
    cleanup. The executable launches no model or interpreter; callers prepare
    and supply external readings.

    *SourceTrees* Parse each source into a content-addressed tree and resolve
    names against imported component interfaces. Expose trees and optional
    Facet differences through the tree command.
  }
}

files.packages/sigilc/config.sigil:
@docs/spec/sigil-config.sigil from SpecWorkspaceConfig import {
  tool settings,
  workspace root,
}
@docs/spec/sigil-reference.sigil from SpecLanguageReference import { source document }
@packages/core/core.sigil from SigilCore import { workspace snapshot }

component SigilCompilerConfig {
  goal {
    Give sigilc one strict reading of its own settings, so that an
    implementation check judges the code files and design sources that the
    workspace owner selected.
  }

  constraints {
    SigilCompilerConfig depends on SigilCore for the tool settings of the
    workspace snapshot, and must not read the workspace config or the local
    override from disk itself.

    SigilCompilerConfig must read only the sigilc namespace of the tool
    settings, and must not check or interpret the tool settings of another
    tool.

    SigilCompilerConfig must reject an unknown key in the sigilc namespace, an
    empty string, a field of the wrong type, and a design root that is not a
    source document of the workspace.

    An implementation check must require the implementation selection and
    must not guess a code selection when it is absent.

    Every path in the implementation selection must be measured from the
    workspace root.
  }

  interface {
    SigilCompilerConfig provides the *implementation selection*, the code
    paths, directories, include and exclude globs, vendor directories and
    empty allowance that choose which code files an implementation check
    judges, and the optional design roots that choose which source documents
    it covers.
  }

  decisions {
    The implementation selection lives with sigilc, so that the shared
    workspace config stays free of settings that only one tool interprets.
  }
}

files.packages/sigilc/scope.sigil:
@packages/sigilc/sources.sigil from SigilSourceIdentity import { CompilerInputSelection }

component SigilComparisonScope {
  goal {
    Resolve requested roots into reproducible *DesignMembership* and
    implementation selection for library callers.
  }

  constraints {
    *StructuralScope* Accept version 1 scope input with workspace-relative design
    roots and an implementation selection. Reject unknown fields, duplicate or
    missing roots, paths outside the workspace, and empty selections unless
    explicitly allowed. compiler.sigil is an ordinary source; imports do not
    imply runtime calls or semantic dependence.
  }

  cases {
    *DependencyClosure* Selecting a source that imports another includes the
    provider and records why it was included. Cycles include each source once.
    An unresolved import adds no target and remains a diagnostic on its source.

    *ScopeChanges* Reordering roots changes focus order while preserving
    membership identity. Removing a source from membership does not delete it or
    its stored reading.
  }

  interface {
    *ScopeInput* Resolve a versioned scope object containing ordered design roots
    and a CompilerInputSelection for implementation sources. Report malformed
    input as an error and expose resolution as a library operation, without
    adding a scope command.

    *FocusOrder* Preserve requested root order as focus priority. List dependency
    additions deterministically after roots with their inclusion reasons. Report
    order separately from unordered membership; order does not schedule
    interpreters.

    DesignMembership Close roots over resolved import targets, owners of
    imported names, and owners of entities or Facets in each included source.
    Include each owner source and record its reason. Preserve physical source
    and canonical owner for every unit, plus applicable configuration, glossary
    context, global diagnostics, and unresolved references. Report roots and
    dependency additions separately; do not infer membership from prose or
    caller metadata.
  }
}

files.packages/sigilc/sources.sigil:
@packages/sigilc/compiler.sigil from SigilSemanticCompiler import { SourceTrees }

component SigilSourceIdentity {
  goal {
    Capture selected files as stable *SourceIdentity* values for SourceTrees
    and implementation alignment.
  }

  constraints {
    SourceIdentity A source identity uses its normalized workspace-relative
    path and *BLAKE3* content checksum. Captured bytes must match a fresh
    filesystem checksum. File identity excludes neighboring sources, selection
    order, and model data.
  }

  cases {
    *FocusedSelection* Selecting *explicit files* leaves unrelated trees
    unread. Repeated paths contribute one file row, and a file-only selection
    has the same identity as an equivalent directory selection.

    SourceIdentity Editing one imported source changes that source row and the
    selected union identity; the unchanged importer's own source identity stays
    stable. Retained captured bytes stay unchanged after a later live edit.
  }

  interface {
    *SemanticInputs* Bind each SourceIdentity to its own parsed tree and resolved
    component interfaces, plus applicable configuration and glossary bytes or their
    absence. A dependency's private edit does not change the importer's basis
    when its interface is unchanged. An unresolved import invalidates its own
    source. Keep production metadata outside source identity.

    *CompilerInputSelection* Select workspace-relative paths and directories
    with include and exclude globs. Support any file extension, omit internal
    and configured vendor trees, and reject accidental empty selection.
    Explicit file selection filters before hashing and does not traverse
    unrelated trees. Refuse symlink crossings, non-regular files, and sources
    that change while read.
  }
}

files.packages/sigilc/store.sigil:
component SigilProjectionStore {
  goal {
    Perform *DisposableCleanup* of cached source projections while preserving
    stored claims readings and authored workspace data.
  }

  interface {
    DisposableCleanup The sigilc clean command removes only the worlds and
    trees entries from the selected store. It tolerates a missing store and
    removes symlink artifacts themselves without following their targets. It
    preserves claims readings, authored sources, workspace configuration, and
    external preparation input. Cleanup takes no world lock and creates no
    cache directories.
  }
}

files.packages/sigilc/vocabulary.sigil:
component SigilClaimsVocabulary {
  goal {
    Own *AcceptedVocabulary* for interpreted design claims and the rules for
    accepting returned claims as data.
  }

  constraints {
    AcceptedVocabulary This component alone declares the accepted claim names
    and generation. Laws read every relation in the set; an incomplete set is
    an operational error before request preparation.

    *AtomDiscipline* Returned text is parsed and admitted as bounded data. It is
    never run as an egglog program, and external files cannot widen accepted
    forms.
  }

  cases {
    AcceptedVocabulary A row naming a relation or property outside the
    accepted set is refused under these AcceptedVocabulary rules.
  }

  interface {
    AcceptedVocabulary Publish the accepted relations, boolean properties,
    numeric measures, seven contract roles, and vocabulary generation. Reject
    names outside these sets. Change the generation when an incompatible row
    shape or accepted name changes.

    AtomDiscipline Bound artifact bytes and row count before validation.
    Accept only literal-argument data rows; reject rules, commands, schedules,
    nested expressions, and non-literal arguments. Refuse the whole artifact
    when it contains executable or malformed top-level content.
  }
}

